1	export type Cell = [number, number];
2	
3	const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
4	
5	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
6	  x === otherX && y === otherY;
7	
8	const isAdjacent = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
9	  Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
10	
11	const isNeighbor = (cell: Cell, other: Cell): boolean =>
12	  isAdjacent(cell, other) && !isSameCell(cell, other);
13	
14	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
15	  liveCells.filter((other) => isNeighbor(cell, other)).length;
16	
17	export function nextGeneration(liveCells: Cell[]): Cell[] {
18	  return liveCells.filter(
19	    (cell) =>
20	      SURVIVAL_NEIGHBOR_COUNTS.includes(countLiveNeighbors(cell, liveCells)),
21	  );
22	}
